public class Redeploy {
    static final List<Object> LEAKED = new ArrayList<>();   // 재배포마다 남는 것
    static long metaspaceKB() {
        for (MemoryPoolMXBean p : ManagementFactory.getMemoryPoolMXBeans())
            if (p.getName().equals("Metaspace")) return p.getUsage().getUsed() >> 10;
        return -1;
    }
    public static void main(String[] a) throws Exception {
        for (int i = 1; i <= rounds; i++) {
            URLClassLoader cl = new URLClassLoader("app-v" + i,
                new URL[]{ dir.toUri().toURL() }, null);
            Class<?> c = cl.loadClass("Solo");
            if (leak) LEAKED.add(c);          // Class 하나만 남겨도 로더 전체가 산다
            else cl.close();
        }
    }
}

